quiz.answer:
package main

import "fmt"

type User struct {
    Name string
    Age  int
}

func greet(u User) string {
    return "Hello, " + u.Name + "!"
}

func isAdult(u User) bool {
    return u.Age >= 20
}

func main() {
    var name string
    var age int
    fmt.Scan(&name, &age)

    user := User{Name: name, Age: age}
    fmt.Println(greet(user))
    fmt.Println("adult:", isAdult(user))
}

