quiz.answer:
package main

import "fmt"

func main() {
    var n int
    fmt.Scan(&n)

    data := map[string]string{}

    for i := 0; i < n; i++ {
        var key, value string
        fmt.Scan(&key, &value)
        data[key] = value
    }

    delete(data, "message")
    fmt.Println("count:", len(data))
    fmt.Println("status: [" + data["status"] + "]")
}
